<script setup lang="ts">import{computed,onMounted,ref}from'vue';import{api}from'../infrastructure/api';const items=ref<any[]>([]),q=ref(''),loading=ref(true);const filtered=computed(()=>items.value.filter(x=>`${x.sku} ${x.name} ${x.category}`.toLowerCase().includes(q.value.toLowerCase())));onMounted(async()=>{items.value=(await api.get('/products')).data;loading.value=false});const status=(p:any)=>!p.isActive?'Inactive':p.stockOnHand<=0?'Out of Stock':p.stockOnHand<=p.reorderLevel?'Low Stock':'In Stock';</script>
<template><div class="page"><div class="panel-head mb-8"><div><p class="eyebrow">INVENTORY</p><h1>Products</h1><p class="subtitle">Your complete product catalog and stock position.</p></div><button class="primary">Add product</button></div><section class="panel"><div class="toolbar"><label class="sr-only" for="search">Search products</label><input id="search" v-model="q" class="search" placeholder="Search by name, SKU, or category"></div><div v-if="loading" class="empty">Loading products…</div><div v-else class="table-wrap"><table><thead><tr><th>Product</th><th>Category</th><th>Stock</th><th>Selling price</th><th>Status</th></tr></thead><tbody><tr v-for="p in filtered" :key="p.id"><td><strong>{{p.name}}</strong><small>{{p.sku}}</small></td><td>{{p.category}}</td><td>{{p.stockOnHand}} {{p.unit}}</td><td>{{new Intl.NumberFormat('id-ID').format(p.sellingPrice)}}</td><td><span class="badge" :class="status(p)==='In Stock'?'ok':'danger'">{{status(p)}}</span></td></tr></tbody></table></div></section></div></template>
